						type = name
						localization = COUNTRY
						scope = root
					}
					variable = {
						type = name
						localization = MEGASTRUCTURE
						scope = root.from
					}
					variable = {
						type = name
						localization = SYSTEM
						scope = root.fromfrom
					}
				}
			}
		}
	}
}

