		is_imperial_authority = yes
	}

	immediate = {
		ruler? = {
			if = {
				limit = {
					NOT = { has_trait = trait_imperial_heir }
				}
				add_trait = {
					trait = trait_imperial_heir
					show_message = no
				}
			}

			set_variable_to_random_value = {
				which = ruler_age_mod
				min = 5
				max = 15
				rounded = yes
			}
			add_age = ruler_age_mod

			random_list = {
				95 = { }
				5 = {
					add_trait = {
						trait = random_common
						show_message = no
					}
					add_trait = {
						trait = random_negative
						show_message = no
					}
					# Variable "leader_pending_negative_traits_unmodified" doesn't exist yet, can't reduce it yet. Checked now made in paragon_2.2200.
					modifier = {
						factor = 0
						exists = owner
						owner = { has_valid_civic = civic_philosopher_king }
					}
				}
			}
		}
	}
}

